import { PlusOutlined } from '@ant-design/icons'
import { Badge, Button, Card, Col, DatePicker, Form, Input, InputNumber, Modal, Row, Select, Tag, TimePicker, Typography } from 'antd'
import React, { memo, useCallback, useMemo, useState } from 'react'
import styles from './ShiftScheduler.module.css'

const { Text } = Typography

function ShiftScheduler({ shifts, volunteers, volunteerMap, addShift, assignVolunteerToShift, removeVolunteerFromShift }) {
  const [addModalVisible, setAddModalVisible] = useState(false)
  const [form] = Form.useForm()

  const sortedShifts = useMemo(() =>
    [...shifts].sort((a, b) => a.date.localeCompare(b.date) || a.startTime.localeCompare(b.startTime)),
  [shifts])

  const activeVolunteers = useMemo(() =>
    volunteers.filter((v) => v.status === 'Active'),
  [volunteers])

  const handleAddShift = useCallback((values) => {
    addShift({
      date: values.date.format('YYYY-MM-DD'),
      startTime: values.startTime.format('HH:mm'),
      endTime: values.endTime.format('HH:mm'),
      location: values.location,
      role: values.role,
      maxVolunteers: values.maxVolunteers,
    })
    form.resetFields()
    setAddModalVisible(false)
  }, [addShift, form])

  const getShiftStatus = useCallback((shift) => {
    const fill = shift.assignedVolunteers.length / shift.maxVolunteers
    if (fill >= 1) return 'success'
    if (fill >= 0.5) return 'warning'
    return 'error'
  }, [])

  return (
    <div className={styles.scheduler}>
      <Button type="primary" icon={<PlusOutlined />} onClick={() => setAddModalVisible(true)} className={styles.addButton}>
        Add Shift
      </Button>

      <Row gutter={[12, 12]}>
        {sortedShifts.map((shift) => (
          <Col xs={24} sm={12} lg={8} key={shift.id}>
            <Badge.Ribbon text={`${shift.assignedVolunteers.length}/${shift.maxVolunteers}`} color={getShiftStatus(shift) === 'success' ? 'green' : getShiftStatus(shift) === 'warning' ? 'gold' : 'red'}>
              <Card size="small" title={shift.role} extra={<Text type="secondary">{shift.date}</Text>} className={styles.shiftCard}>
                <div className={styles.shiftDetails}>
                  <Text>{shift.startTime} - {shift.endTime}</Text>
                  <Text type="secondary">{shift.location}</Text>
                </div>
                <div className={styles.assignedList}>
                  {shift.assignedVolunteers.map((vId) => {
                    const vol = volunteerMap[vId]
                    return vol ? (
                      <Tag key={vId} closable onClose={() => removeVolunteerFromShift(shift.id, vId)}>
                        {vol.name}
                      </Tag>
                    ) : null
                  })}
                </div>
                {shift.assignedVolunteers.length < shift.maxVolunteers && (
                  <Select
                    placeholder="Add volunteer..."
                    size="small"
                    className={styles.assignSelect}
                    onChange={(vId) => assignVolunteerToShift(shift.id, vId)}
                    value={null}
                    options={activeVolunteers
                        .filter((v) => !shift.assignedVolunteers.includes(v.id))
                        .map((v) => ({ value: v.id, label: v.name }))}
                  />
                )}
              </Card>
            </Badge.Ribbon>
          </Col>
        ))}
      </Row>

      <Modal title="Add Shift" open={addModalVisible} onCancel={() => setAddModalVisible(false)} footer={null}>
        <Form form={form} layout="vertical" onFinish={handleAddShift}>
          <Form.Item name="date" label="Date" rules={[{ required: true, message: 'Required' }]}><DatePicker className={styles.fullWidth} /></Form.Item>
          <Form.Item name="startTime" label="Start Time" rules={[{ required: true, message: 'Required' }]}><TimePicker format="HH:mm" className={styles.fullWidth} /></Form.Item>
          <Form.Item name="endTime" label="End Time" rules={[{ required: true, message: 'Required' }]}><TimePicker format="HH:mm" className={styles.fullWidth} /></Form.Item>
          <Form.Item name="location" label="Location" rules={[{ required: true, message: 'Required' }]}><Input /></Form.Item>
          <Form.Item name="role" label="Role" rules={[{ required: true, message: 'Required' }]}>
            <Select options={['Canvassing', 'Phone Banking', 'Data Entry', 'Event Setup', 'Transportation'].map((r) => ({ value: r, label: r }))} />
          </Form.Item>
          <Form.Item name="maxVolunteers" label="Max Volunteers" rules={[{ required: true, message: 'Required' }]}>
            <InputNumber min={1} max={50} className={styles.fullWidth} />
          </Form.Item>
          <Form.Item><Button type="primary" htmlType="submit" block>Create Shift</Button></Form.Item>
        </Form>
      </Modal>
    </div>
  )
}

export default memo(ShiftScheduler)
