import { ClearOutlined, PlusOutlined, TeamOutlined } from '@ant-design/icons'
import { Button, Card, Checkbox, Form, Input, Modal, Select, Statistic, Typography } from 'antd'
import React, { memo, useCallback, useState } from 'react'
import styles from './VolunteerToolPanel.module.css'

const { Title, Text } = Typography

const SKILLS = ['Canvassing', 'Phone Banking', 'Data Entry', 'Event Setup', 'Social Media', 'Transportation']
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
const STATUSES = ['Active', 'Inactive', 'On Leave']

function VolunteerToolPanel({ filters, updateFilters, clearFilters, addVolunteer, summaryStats }) {
  const [addModalVisible, setAddModalVisible] = useState(false)
  const [form] = Form.useForm()

  const handleAdd = useCallback((values) => {
    addVolunteer({ ...values, status: 'Active' })
    form.resetFields()
    setAddModalVisible(false)
  }, [addVolunteer, form])

  return (
    <div className={styles.toolPanel}>
      <Title level={5} className={styles.panelTitle}><TeamOutlined /> Volunteers</Title>

      <Card size="small" className={styles.statsCard}>
        <Statistic title="Active" value={summaryStats.activeVolunteers} suffix={`/ ${summaryStats.totalVolunteers}`} />
        <Statistic title="Total Hours" value={summaryStats.totalHours} className={styles.statItem} />
        <Statistic title="Open Tasks" value={summaryStats.openTasks} className={styles.statItem} />
      </Card>

      <Button type="primary" icon={<PlusOutlined />} onClick={() => setAddModalVisible(true)} block className={styles.addButton}>
        Add Volunteer
      </Button>

      <Card size="small" className={styles.card}>
        <Text strong>Search</Text>
        <Input placeholder="Name or email..." value={filters.search} onChange={(e) => updateFilters({ search: e.target.value })} allowClear className={styles.fullWidth} />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Filter by Skill</Text>
        <Select placeholder="All Skills" value={filters.skill} onChange={(v) => updateFilters({ skill: v || null })} allowClear className={styles.fullWidth} options={SKILLS.map((s) => ({ value: s, label: s }))} />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Filter by Day</Text>
        <Select placeholder="Any Day" value={filters.availability} onChange={(v) => updateFilters({ availability: v || null })} allowClear className={styles.fullWidth} options={DAYS.map((d) => ({ value: d, label: d }))} />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Status</Text>
        <Select placeholder="All" value={filters.status} onChange={(v) => updateFilters({ status: v || null })} allowClear className={styles.fullWidth} options={STATUSES.map((s) => ({ value: s, label: s }))} />
      </Card>

      <Button icon={<ClearOutlined />} onClick={clearFilters} block>Clear Filters</Button>

      <Modal title="Add Volunteer" open={addModalVisible} onCancel={() => setAddModalVisible(false)} footer={null}>
        <Form form={form} layout="vertical" onFinish={handleAdd}>
          <Form.Item name="name" label="Name" rules={[{ required: true, message: 'Required' }]}><Input /></Form.Item>
          <Form.Item name="email" label="Email" rules={[{ required: true, type: 'email', message: 'Valid email required' }]}><Input /></Form.Item>
          <Form.Item name="phone" label="Phone"><Input /></Form.Item>
          <Form.Item name="city" label="City"><Input /></Form.Item>
          <Form.Item name="skills" label="Skills"><Checkbox.Group options={SKILLS} /></Form.Item>
          <Form.Item name="availability" label="Availability"><Checkbox.Group options={DAYS} /></Form.Item>
          <Form.Item><Button type="primary" htmlType="submit" block>Add Volunteer</Button></Form.Item>
        </Form>
      </Modal>
    </div>
  )
}

export default memo(VolunteerToolPanel)
