import { ArrowLeftOutlined, ArrowRightOutlined, PlusOutlined } from '@ant-design/icons'
import { Button, Card, Col, Form, Input, Modal, Row, Select, Tag, Typography } from 'antd'
import React, { memo, useCallback, useMemo, useState } from 'react'
import styles from './TaskBoard.module.css'

const { Text } = Typography

const PRIORITY_COLORS = { High: 'red', Medium: 'orange', Low: 'blue' }
const STATUS_ORDER = ['To Do', 'In Progress', 'Completed']

function TaskBoard({ tasks, volunteerMap, addTask, updateTaskStatus, volunteers }) {
  const [addModalVisible, setAddModalVisible] = useState(false)
  const [form] = Form.useForm()

  const tasksByStatus = useMemo(() => {
    const grouped = { 'To Do': [], 'In Progress': [], 'Completed': [] }
    tasks.forEach((t) => {
      if (grouped[t.status]) grouped[t.status].push(t)
    })
    return grouped
  }, [tasks])

  const handleAdd = useCallback((values) => {
    addTask({ ...values, assignedTo: values.assignedTo || null })
    form.resetFields()
    setAddModalVisible(false)
  }, [addTask, form])

  const moveTask = useCallback((taskId, direction) => {
    const task = tasks.find((t) => t.id === taskId)
    if (!task) return
    const currentIdx = STATUS_ORDER.indexOf(task.status)
    const newIdx = currentIdx + direction
    if (newIdx >= 0 && newIdx < STATUS_ORDER.length) {
      updateTaskStatus(taskId, STATUS_ORDER[newIdx])
    }
  }, [tasks, updateTaskStatus])

  return (
    <div className={styles.board}>
      <Button type="primary" icon={<PlusOutlined />} onClick={() => setAddModalVisible(true)} className={styles.addButton}>
        Add Task
      </Button>

      <Row gutter={[12, 12]}>
        {STATUS_ORDER.map((status) => (
          <Col xs={24} md={8} key={status}>
            <Card title={status} extra={<Tag>{tasksByStatus[status].length}</Tag>} size="small" className={styles.column}>
              {tasksByStatus[status].map((task) => {
                const assignee = task.assignedTo ? volunteerMap[task.assignedTo] : null
                return (
                  <Card key={task.id} size="small" className={styles.taskCard}>
                    <div className={styles.taskHeader}>
                      <Text strong>{task.title}</Text>
                      <Tag color={PRIORITY_COLORS[task.priority]}>{task.priority}</Tag>
                    </div>
                    <Text type="secondary" className={styles.taskDesc}>{task.description}</Text>
                    <div className={styles.taskMeta}>
                      {assignee && <Tag>{assignee.name}</Tag>}
                      <Text type="secondary" className={styles.dueDate}>Due: {task.dueDate}</Text>
                    </div>
                    <div className={styles.taskActions}>
                      {status !== 'To Do' && (
                        <Button size="small" icon={<ArrowLeftOutlined />} onClick={() => moveTask(task.id, -1)} />
                      )}
                      {status !== 'Completed' && (
                        <Button size="small" icon={<ArrowRightOutlined />} onClick={() => moveTask(task.id, 1)} />
                      )}
                    </div>
                  </Card>
                )
              })}
            </Card>
          </Col>
        ))}
      </Row>

      <Modal title="Add Task" open={addModalVisible} onCancel={() => setAddModalVisible(false)} footer={null}>
        <Form form={form} layout="vertical" onFinish={handleAdd}>
          <Form.Item name="title" label="Title" rules={[{ required: true, message: 'Required' }]}><Input /></Form.Item>
          <Form.Item name="description" label="Description"><Input.TextArea rows={3} /></Form.Item>
          <Form.Item name="priority" label="Priority" rules={[{ required: true, message: 'Required' }]}>
            <Select options={['High', 'Medium', 'Low'].map((p) => ({ value: p, label: p }))} />
          </Form.Item>
          <Form.Item name="assignedTo" label="Assign To">
            <Select allowClear placeholder="Unassigned" options={volunteers.filter((v) => v.status === 'Active').map((v) => ({ value: v.id, label: v.name }))} />
          </Form.Item>
          <Form.Item name="dueDate" label="Due Date" rules={[{ required: true, message: 'Required' }]}><Input type="date" /></Form.Item>
          <Form.Item><Button type="primary" htmlType="submit" block>Create Task</Button></Form.Item>
        </Form>
      </Modal>
    </div>
  )
}

export default memo(TaskBoard)
