import { Table, Tag } from 'antd'
import React, { memo, useMemo } from 'react'
import styles from './VolunteerDirectory.module.css'

const STATUS_COLORS = { 'Active': 'green', 'Inactive': 'default', 'On Leave': 'orange' }
const SKILL_COLORS = { 'Canvassing': 'blue', 'Phone Banking': 'purple', 'Data Entry': 'cyan', 'Event Setup': 'green', 'Social Media': 'magenta', 'Transportation': 'orange' }

function VolunteerDirectory({ volunteers, updateVolunteer }) {
  const columns = useMemo(() => [
    { title: 'Name', dataIndex: 'name', key: 'name', width: 150, sorter: (a, b) => a.name.localeCompare(b.name) },
    { title: 'Email', dataIndex: 'email', key: 'email', width: 180 },
    { title: 'Phone', dataIndex: 'phone', key: 'phone', width: 130 },
    { title: 'City', dataIndex: 'city', key: 'city', width: 120 },
    { title: 'Skills', dataIndex: 'skills', key: 'skills', width: 200,
      render: (skills) => skills.map((s) => <Tag key={s} color={SKILL_COLORS[s]}>{s}</Tag>),
    },
    { title: 'Status', dataIndex: 'status', key: 'status', width: 100,
      render: (status, record) => (
        <Tag
          color={STATUS_COLORS[status]}
          className={styles.clickableTag}
          onClick={() => {
            const next = status === 'Active' ? 'Inactive' : 'Active'
            updateVolunteer(record.id, { status: next })
          }}
        >
          {status}
        </Tag>
      ),
    },
    { title: 'Hours', dataIndex: 'hoursLogged', key: 'hoursLogged', width: 80, sorter: (a, b) => a.hoursLogged - b.hoursLogged },
    { title: 'Last Active', dataIndex: 'lastActive', key: 'lastActive', width: 110, sorter: (a, b) => a.lastActive.localeCompare(b.lastActive) },
  ], [updateVolunteer])

  return (
    <div className={styles.directory}>
      <Table
        columns={columns}
        dataSource={volunteers.map((v) => ({ ...v, key: v.id }))}
        size="small"
        pagination={{ pageSize: 15 }}
        scroll={{ x: 1100 }}
      />
    </div>
  )
}

export default memo(VolunteerDirectory)
