import { Tabs } from 'antd'
import React from 'react'
import useVolunteerData from './hooks/useVolunteerData.jsx'
import VolunteerToolPanel from './VolunteerToolPanel.jsx'
import VolunteerDirectory from './VolunteerDirectory.jsx'
import ShiftScheduler from './ShiftScheduler.jsx'
import TaskBoard from './TaskBoard.jsx'
import styles from './VolunteerContainer.module.css'

const VolunteerContainer = () => {
  const data = useVolunteerData()

  const tabItems = [
    {
      key: 'directory',
      label: `Volunteers (${data.filteredVolunteers.length})`,
      children: <VolunteerDirectory volunteers={data.filteredVolunteers} updateVolunteer={data.updateVolunteer} />,
    },
    {
      key: 'shifts',
      label: `Shifts (${data.shifts.length})`,
      children: <ShiftScheduler shifts={data.shifts} volunteers={data.volunteers} volunteerMap={data.volunteerMap} addShift={data.addShift} assignVolunteerToShift={data.assignVolunteerToShift} removeVolunteerFromShift={data.removeVolunteerFromShift} />,
    },
    {
      key: 'tasks',
      label: `Tasks (${data.tasks.length})`,
      children: <TaskBoard tasks={data.tasks} volunteerMap={data.volunteerMap} addTask={data.addTask} updateTaskStatus={data.updateTaskStatus} volunteers={data.volunteers} />,
    },
  ]

  return (
    <div className={styles.container}>
      <VolunteerToolPanel
        filters={data.filters}
        updateFilters={data.updateFilters}
        clearFilters={data.clearFilters}
        addVolunteer={data.addVolunteer}
        summaryStats={data.summaryStats}
      />
      <div className={styles.content}>
        <Tabs items={tabItems} defaultActiveKey="directory" />
      </div>
    </div>
  )
}

export default VolunteerContainer
