import { useCallback, useMemo, useState } from 'react'
import { sampleVolunteers, sampleShifts, sampleTasks } from '../data/sampleVolunteerData.js'

const useVolunteerData = () => {
  const [volunteers, setVolunteers] = useState(sampleVolunteers)
  const [shifts, setShifts] = useState(sampleShifts)
  const [tasks, setTasks] = useState(sampleTasks)
  const [filters, setFilters] = useState({ search: '', skill: null, availability: null, status: null })

  const filteredVolunteers = useMemo(() => {
    let result = volunteers
    if (filters.search) {
      const q = filters.search.toLowerCase()
      result = result.filter((v) => v.name.toLowerCase().includes(q) || v.email.toLowerCase().includes(q))
    }
    if (filters.skill) {
      result = result.filter((v) => v.skills.includes(filters.skill))
    }
    if (filters.availability) {
      result = result.filter((v) => v.availability.includes(filters.availability))
    }
    if (filters.status) {
      result = result.filter((v) => v.status === filters.status)
    }
    return result
  }, [volunteers, filters])

  const addVolunteer = useCallback((data) => {
    setVolunteers((prev) => [...prev, { ...data, id: `v${Date.now()}`, hoursLogged: 0, lastActive: new Date().toISOString().split('T')[0], joinDate: new Date().toISOString().split('T')[0] }])
  }, [])

  const updateVolunteer = useCallback((id, data) => {
    setVolunteers((prev) => prev.map((v) => v.id === id ? { ...v, ...data } : v))
  }, [])

  const removeVolunteer = useCallback((id) => {
    setVolunteers((prev) => prev.filter((v) => v.id !== id))
  }, [])

  const addShift = useCallback((data) => {
    setShifts((prev) => [...prev, { ...data, id: `s${Date.now()}`, assignedVolunteers: [] }])
  }, [])

  const assignVolunteerToShift = useCallback((shiftId, volunteerId) => {
    setShifts((prev) => prev.map((s) => {
      if (s.id === shiftId && !s.assignedVolunteers.includes(volunteerId) && s.assignedVolunteers.length < s.maxVolunteers) {
        return { ...s, assignedVolunteers: [...s.assignedVolunteers, volunteerId] }
      }
      return s
    }))
  }, [])

  const removeVolunteerFromShift = useCallback((shiftId, volunteerId) => {
    setShifts((prev) => prev.map((s) => {
      if (s.id === shiftId) {
        return { ...s, assignedVolunteers: s.assignedVolunteers.filter((id) => id !== volunteerId) }
      }
      return s
    }))
  }, [])

  const addTask = useCallback((data) => {
    setTasks((prev) => [...prev, { ...data, id: `t${Date.now()}`, status: 'To Do', createdDate: new Date().toISOString().split('T')[0] }])
  }, [])

  const updateTaskStatus = useCallback((taskId, newStatus) => {
    setTasks((prev) => prev.map((t) => t.id === taskId ? { ...t, status: newStatus } : t))
  }, [])

  const updateFilters = useCallback((newFilters) => {
    setFilters((prev) => ({ ...prev, ...newFilters }))
  }, [])

  const clearFilters = useCallback(() => {
    setFilters({ search: '', skill: null, availability: null, status: null })
  }, [])

  const volunteerMap = useMemo(() => {
    const map = {}
    volunteers.forEach((v) => {
      map[v.id] = v
    })
    return map
  }, [volunteers])

  const summaryStats = useMemo(() => ({
    totalVolunteers: volunteers.length,
    activeVolunteers: volunteers.filter((v) => v.status === 'Active').length,
    totalHours: volunteers.reduce((sum, v) => sum + v.hoursLogged, 0),
    upcomingShifts: shifts.length,
    openTasks: tasks.filter((t) => t.status !== 'Completed').length,
  }), [volunteers, shifts, tasks])

  return {
    volunteers, filteredVolunteers, shifts, tasks, filters, volunteerMap, summaryStats,
    addVolunteer, updateVolunteer, removeVolunteer,
    addShift, assignVolunteerToShift, removeVolunteerFromShift,
    addTask, updateTaskStatus, updateFilters, clearFilters,
  }
}

export default useVolunteerData
